        }
        else {
            tokens.darkColor[key as keyof Omit<ColorToken, 'theme'>] =
                modifyHSL(
                    hex as string,
                    null,
                    s => s * 0.6,
                    l => invertLightness(l, DARK_NEUTRAL_L_MIN, DARK_NEUTRAL_L_MAX)
